--- Looks up Russian translation for a passive node or name.
--- Safe fallback: returns original English display name if not found.
---@param nodeOrName table|string|number|nil
---@return string|nil
function TreeNodesRU:Get(nodeOrName)
    if not nodeOrName then
        return nil
    end
    local t = type(nodeOrName)
    if t == "table" then
        local sk = nodeOrName.skill or nodeOrName.id
        if sk and self.bySkill[sk] then
            return self.bySkill[sk]
        end
        local name = nodeOrName.dn or nodeOrName.name
        if name and self.byName[name] then
            return self.byName[name]
        end
        return name
    elseif t == "number" then
        return self.bySkill[nodeOrName]
    elseif t == "string" then
        return self.byName[nodeOrName] or nodeOrName
    end
    return nil
end

return TreeNodesRU
